output_text:
[
  {
    "id": "must_take_cart",
    "text": "The agent is obliged to obtain a shopping cart during the trip.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "hasCart"
    }
  },
  {
    "id": "no_exit_without_cart",
    "text": "The agent is prohibited from leaving the store without a shopping cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "must_use_cart_station",
    "text": "The agent is obliged to interact with the cart station at cell (1,7).",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": {
        "and": [
          "INTERACT",
          "at(1,7)"
        ]
      }
    }
  },
  {
    "id": "cart_required_past_bay",
    "text": "The agent is prohibited from entering the main shopping path beyond the cart bay without a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          {
            "or": [
              "at(2,7)",
              "at(3,7)",
              "at(4,7)",
              "at(5,7)",
              "at(6,7)",
              "at(6,6)",
              "at(7,6)",
              "at(8,6)",
              "at(8,7)",
              "at(9,7)",
              "at(10,7)",
              "at(11,7)"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "no_vertical_without_cart",
    "text": "The agent is prohibited from moving north or south unless they have a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          {
            "or": [
              "N",
              "S"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "no_shelf_interaction_without_cart",
    "text": "The agent is prohibited from interacting at cell (6,6) without a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "at(6,6)",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "interact_only_at_allowed_spots",
    "text": "The agent is prohibited from interacting anywhere except at the cart location or the item location.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          {
            "not": {
              "or": [
                "at(1,7)",
                "at(6,6)"
              ]
            }
          }
        ]
      }
    }
  },
  {
    "id": "no_westbound_travel",
    "text": "The agent is prohibited from moving west, as if the store has a one-way walking rule.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": "W"
    }
  }
]
